  // 添加节流函数
  throttle(func, delay) {
    if (this.isScrolling) return;
    this.isScrolling = true;
    func();
    setTimeout(() => {
      this.isScrolling = false;
    }, delay);
  }

  connectedCallback() {
    this.render();
    this.addEventListeners();
    this.updateContent(); // 确保首次加载时更新内容
  }

  addEventListeners() {
    const content = this.shadowRoot.querySelector('.content-container');
    content.addEventListener('wheel', (e) => {
      e.preventDefault();
      this.throttle(() => {
        const delta = e.deltaY;
        if (delta > 0 && this.currentIndex < this.changeContent.length - 1) {
          this.currentIndex++;
        } else if (delta < 0 && this.currentIndex > 0) {
          this.currentIndex--;
        }
        this.updateContent();
      }, this.throttleTimeout);
    });

    // 添加 flat-text span 元素的点击事件监听
    const flatTextSpans = this.shadowRoot.querySelectorAll('.flat-text span');
    flatTextSpans.forEach((span, index) => {
      span.addEventListener('click', () => {
        if (index !== this.currentIndex) {
          this.currentIndex = index;
          this.updateContent();
        }
      });
    });
  }

  updateContent() {
    const item = this.changeContent[this.currentIndex];
    const content = this.shadowRoot.querySelector('.content-container');
    const scrollBar = this.shadowRoot.querySelector('.scroll-bar');
    const svgPaths = this.shadowRoot.querySelectorAll('svg path');
    console.log(svgPaths);

    // 更新内容
    content.innerHTML = `
      <div>
        <img src="${item.imgs}" alt="agricultural-change-${
      this.currentIndex + 1
    }" />
      </div>
      <div class="agricultural-change-content-text-container">
        <div class="agricultural-change-content-text">
          <h6>简介</h6>
          <div class="text-wrapper">
            <p class="paragraph-1 ${this.expanded.profile ? 'expanded' : ''}">${
      item.profile
    }</p>
            <button class="expand-btn ${
              this.expanded.profile ? 'expanded' : ''
            }" data-type="profile">
              ${this.expanded.profile ? '收起' : '点击更多'}
            </button>
          </div>
          <h6>种植方式</h6>
          <div class="text-wrapper">
            <p class="paragraph-2 ${this.expanded.method ? 'expanded' : ''}">${
      item.method
    }</p>
            <button class="expand-btn ${
              this.expanded.method ? 'expanded' : ''
            }" data-type="method">
              ${this.expanded.method ? '收起' : '点击更多'}
            </button>
          </div>
        </div>
      </div>
    `;

    // 更新滚动条位置
    scrollBar.style.transform = `translateY(${this.currentIndex * 100}%)`;

    // 更新特定 SVG 路径颜色
    const group1 = [5, 6, 7];
    const group2 = [13, 14, 15];
    const group3 = [21, 22, 23];
    const group4 = [29, 30, 31];

    // 更新第一组
    group1.forEach((index, i) => {
      if (svgPaths[index]) {
        svgPaths[index].setAttribute(
          'fill',
          this.colors[this.currentIndex].group1[i]
        );
      }
    });

    // 更新第二组
    group2.forEach((index, i) => {
      if (svgPaths[index]) {
        svgPaths[index].setAttribute(
          'fill',
          this.colors[this.currentIndex].group2[i]
        );
      }
    });

    // 更新第三组
    group3.forEach((index, i) => {
      if (svgPaths[index]) {
        svgPaths[index].setAttribute(
          'fill',
          this.colors[this.currentIndex].group3[i]
        );
      }
    });

    // 更新第四组
    group4.forEach((index, i) => {
      if (svgPaths[index]) {
        svgPaths[index].setAttribute(
          'fill',
          this.colors[this.currentIndex].group4[i]
        );
      }
    });

    // 添加展开/收起按钮事件监听
    const expandBtns = content.querySelectorAll('.expand-btn');
    expandBtns.forEach((btn) => {
      const type = btn.dataset.type;
      const textElement = btn.previousElementSibling;

      if (
        textElement.scrollHeight > textElement.clientHeight ||
        this.expanded[type]
      ) {
        btn.classList.add('visible');
      }

      btn.addEventListener('click', (e) => {
        this.expanded[type] = !this.expanded[type];
        this.updateContent();
      });
    });

    // 获取所有 <circle> 元素
    const circles = this.shadowRoot.querySelectorAll('circle');

    // 遍历每一个 <circle> 元素，根据 currentIndex 设置透明度
    circles.forEach((circle, index) => {
      circle.addEventListener('click', () => {
        if (index !== this.currentIndex) {
          this.currentIndex = index;
          this.updateContent();
        }
      });
      const opacity = index === this.currentIndex ? 1 : 0; // 只有当前索引的 <circle> 不透明
      circle.setAttribute('fill-opacity', opacity);
    });

    // 获取所有 <span> 元素
    const spans = this.shadowRoot.querySelectorAll('.flat-text span');

    // 遍历每一个 <span> 元素，根据 currentIndex 设置字体颜色
    spans.forEach((span, index) => {
      const color = index === this.currentIndex ? '#137C41' : '';
      span.style.color = color;
    });
  }

